/* From Uiverse.io by themrsami  - Tags: input */
.__UIV_SCOPE__ .search-container {
  position: relative;
  width: 290px;
}

.__UIV_SCOPE__ .search-bar {
  position: relative;
  display: flex;
  align-items: center;
  background-color: #1e1e1e;
  border-radius: 8px;
  padding: 10px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .search-input {
  width: 100%;
  border: none;
  background: none;
  color: #fff;
  font-size: 16px;
  padding: 10px;
  outline: none;
}

.__UIV_SCOPE__ .search-input::placeholder {
  color: #aaa;
}

.__UIV_SCOPE__ .search-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px;
  background-color: #333;
  border-radius: 50%;
  margin-left: 10px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.__UIV_SCOPE__ .search-icon svg {
  fill: #fff;
}

.__UIV_SCOPE__ .search-icon:hover {
  background-color: #555;
}

.__UIV_SCOPE__ .search-bar:hover {
  box-shadow: 0 0 15px rgba(255, 255, 255, 0.2);
}

.__UIV_SCOPE__ .search-bar:focus-within {
  box-shadow: 0 0 30px rgba(255, 255, 255, 0.4);
}

.__UIV_SCOPE__ .glow {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 200%;
  border-radius: 100px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.1), transparent);
  transition: all 0.5s ease;
  transform: translate(-50%, -50%) scale(0);
  z-index: -1;
}

.__UIV_SCOPE__ .search-bar:hover + .glow {
  transform: translate(-50%, -50%) scale(1);
}

.__UIV_SCOPE__ .search-bar:focus-within + .glow {
  transform: translate(-50%, -50%) scale(1.2);
  background: radial-gradient(circle, rgba(255, 255, 255, 0.2), transparent);
}
